/bin/bash -lc "mkdir -p shared/dns
python3 - <<'PY'
from pathlib import Path
import re
records={
'open.ministero.gov':46,'shop.example.com':16,'ai.research.lab.net':22,'data.research.lab.net':23,'api.startup.io':44,'ci.tools.net':25,'archive.foundation.org':42,'studenti.unibo.it':29,'servizi.ministero.gov':47,'blog.example.com':17,'dept.company.com':18,'intranet.company.com':19,'status.platform.io':45,'local.news.info':48,'media.news.info':49,'api.service.com':20,'docs.project.org':43,'vpn.university.edu':26,'servizi.comune.it':30,'dev.lab.net':24,'courses.university.edu':27,'portal.campus.edu':28,'dati.regione.it':31,'mail.servizi.ministero.gov':47,'mail.company.com':7,'mail.dept.company.com':18,'mail.university.edu':11}
mx={'servizi.ministero.gov':'mail.servizi.ministero.gov','company.com':'mail.company.com','dept.company.com':'mail.dept.company.com','university.edu':'mail.university.edu'}
zones=['ministero.gov','example.com','lab.net','startup.io','tools.net','foundation.org','unibo.it','company.com','platform.io','news.info','service.com','project.org','university.edu','comune.it','campus.edu','regione.it']
ips={}
for n in set(records.values()) | {1}:
 s=Path(f'pc{n}.startup').read_text(); ips[n]=re.search(r\"inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/24\",s).group(1)
config='''options {
    directory \"/shared/dns\";
    pid-file \"/run/lab-named.pid\";
    listen-on port 53 { any; };
    listen-on-v6 { none; };
    allow-query { any; };
    allow-recursion { 10.16.0.0/16; localhost; };
    recursion yes;
    dnssec-validation auto;
};
'''
for zone in zones:
 config+=f'zone \"{zone}\" {{ type master; file \"/shared/dns/db.{zone}\"; }};\\n'
 lines=['"'$TTL 300'"',f'@ IN SOA ns.{zone}. hostmaster.{zone}. ( 2026110301 3600 600 604800 300 )',f'@ IN NS ns.{zone}.',f'ns IN A {ips[1]}']
 for name,n in records.items():
  if name.endswith('.'+zone): lines.append(f'{name[:-len(zone)-1]} IN A {ips[n]}')
 for name,target in mx.items():
  if name==zone or name.endswith('.'+zone): lines.append(f'{\"@\" if name==zone else name[:-len(zone)-1]} IN MX 10 {target}.')
 Path(f'shared/dns/db.{zone}').write_text('\\n'.join(lines)+'\\n')
Path('shared/dns/named.conf').write_text(config)
for n in range(1,61):
 p=Path(f'pc{n}.startup'); s=p.read_text(); s+='\\n# DNS del laboratorio, mantenendo gli eventuali resolver preesistenti.\\n' + ('''if "'! pgrep -x named >/dev/null 2>&1; then
  named -c /shared/dns/named.conf
fi
'"''' if n==1 else '') + f'''if "'! grep -q '"'"'^nameserver {ips[1]}$'"' /etc/resolv.conf; then
  {{ echo 'nameserver {ips[1]}'; cat /etc/resolv.conf; }} > /tmp/lab-resolv.conf
  cat /tmp/lab-resolv.conf > /etc/resolv.conf
fi
'''; p.write_text(s)
PY
sh -n pc*.startup"

